struct PricingStrategy {                                      // Strategy
    virtual ~PricingStrategy() = default;
    virtual double price(double qty) const = 0;
};

struct WholesalePricing final : PricingStrategy {             // ConcreteStrategy
    double price(double qty) const override { return qty * 7.49; }
};

class Checkout {                                              // Context
public:
    explicit Checkout(std::unique_ptr<PricingStrategy> s) : strategy_(std::move(s)) {}
    double total(double qty) const { return strategy_->price(qty); }
private:
    std::unique_ptr<PricingStrategy> strategy_;
};

struct RetailPricing { static double price(double q) { return q * 9.99; } };

template <class Pricing = RetailPricing>     // compile-time strategy
class Checkout {
public:
    double total(double qty) const { return Pricing::price(qty); }  // inlined
};

Checkout<RetailPricing> retail;              // two distinct types,
Checkout<WholesalePricing> wholesale;        // no vtable and no allocation
